function convertSerialDate(serial) {
  const base = new Date(Date.UTC(1899, 11, 30));
  const ms = serial * 24 * 60 * 60 * 1000;
  return new Date(base.getTime() + ms).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });
}

const groupedQuotes = {};

for (const item of items) {
  const row = item.json;
  const quoteId = row["Quote ID"];

  if (!groupedQuotes[quoteId]) {
    groupedQuotes[quoteId] = {
      quote_accepted: false,
      quote_expired: false,
      quote_id: quoteId,
      quote_date: convertSerialDate(row["Quote Date"]),
      quote_validUntil: convertSerialDate(row["Valid Until"]),
      sales_rep: row["Sales Representative"],
      client_name: row["Client Full Name"],
      client_company: row["Client Organization"],
      client_address: row["Client Address"],
      client_email: row["Client Email"],
      client_phone: row["Client Phone Number"],
      discount: parseFloat(row["Discount (%)"]) || 0,
      tax: parseFloat(row["Applicable Tax"]) || 0,
      issuer_name: "Ravi Kapoor",
      issuer_company: "DataStream Analytics Pvt. Ltd.",
      issuer_address: "601 Tech Park, HSR Layout, Bengaluru, KA 560102",
      issuer_email: "sales@datastream-analytics.com",
      issuer_phone: "+91 98765 43210",
      issuer_website: "www.datastream-analytics.com",
      terms: "Invoices are due within 15 days from the date of issue.",
      note: "Looking forward to a long-term collaboration. Let us know for any clarifications.",
      items: []
    };
  }

  groupedQuotes[quoteId].items.push({
    name: row["Service Name"],
    description: row["Service Details"],
    quantity: parseInt(row["Units"]) || 1,
    price: parseFloat(row["Unit Price (INR)"]) || 0
  });
}

const quote = Object.values(groupedQuotes)[0]; // Return the first (and likely only) quote
return [{ json: quote }];
